CREATE TABLE shift_categories (id BIGSERIAL PRIMARY KEY,name VARCHAR(50) NOT NULL,color VARCHAR(7),default_start_time TIME NOT NULL,default_end_time TIME NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_shift_category_name UNIQUE(name));
CREATE TABLE shifts (id BIGSERIAL PRIMARY KEY,shift_category_id BIGINT NOT NULL REFERENCES shift_categories(id),starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',location_id BIGINT NOT NULL,required_employees INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_shift_location_start ON shifts(location_id,starts_at); CREATE INDEX idx_shift_status_start ON shifts(status,starts_at);
CREATE TABLE shift_assignments (id BIGSERIAL PRIMARY KEY,shift_id BIGINT NOT NULL REFERENCES shifts(id),employee_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ASSIGNED',responded_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_shift_employee UNIQUE(shift_id,employee_id));
CREATE INDEX idx_assignment_employee ON shift_assignments(employee_id);
CREATE TABLE employee_availability (id BIGSERIAL PRIMARY KEY,employee_id BIGINT NOT NULL,day_of_week VARCHAR(10) NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,type VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_availability_employee_day ON employee_availability(employee_id,day_of_week);
